function getPasswordRecoveryLocation(href) {
  const url = new URL(href);
  const hash = new URLSearchParams(url.hash.slice(1));
  const requested =
    url.searchParams.get("password_recovery") === "1" ||
    hash.get("type") === "recovery";
  const failed = hash.has("error") || url.searchParams.has("error");
  return {
    requested,
    hasCallback: hash.has("access_token") || hash.has("refresh_token") || url.searchParams.has("code"),
    error: requested && failed
      ? "Atkūrimo nuoroda nebegalioja arba jau panaudota. Paprašykite naujos nuorodos."
      : "",
  };
}

function rememberPasswordRecoveryUser(userId) {
  try {
    window.sessionStorage.setItem("password-recovery-user", JSON.stringify({ userId, at: Date.now() }));
  } catch { /* Recovery also works when browser storage is unavailable. */ }
}

function rememberedPasswordRecoveryUser() {
  try {
    const saved = JSON.parse(window.sessionStorage.getItem("password-recovery-user") || "null");
    return saved?.userId && Date.now() - saved.at < 60 * 60 * 1000 ? saved.userId : "";
  } catch { return ""; }
}

function passwordRecoveryRedirectUrl() {
  const url = new URL(window.location.pathname, window.location.origin);
  url.searchParams.set("password_recovery", "1");
  return url.href;
}

function clearPasswordRecoveryUrl() {
  try { window.sessionStorage.removeItem("password-recovery-user"); } catch { /* Optional storage. */ }
  const url = new URL(window.location.href);
  url.searchParams.delete("password_recovery");
  for (const name of ["error", "error_code", "error_description"]) {
    url.searchParams.delete(name);
  }
  const hash = new URLSearchParams(url.hash.slice(1));
  if (hash.has("access_token") || hash.has("refresh_token") ||
      hash.get("type") === "recovery" || hash.has("error")) {
    url.hash = "";
  }
  window.history.replaceState({}, "", `${url.pathname}${url.search}${url.hash}`);
}

function passwordRecoveryErrorMessage(error, fallback) {
  const code = error?.code || "";
  if (code === "over_email_send_rate_limit" || code === "over_request_rate_limit" ||
      error?.status === 429) {
    return "Per daug bandymų. Palaukite kelias minutes ir bandykite dar kartą.";
  }
  if (code === "weak_password") {
    return "Šis slaptažodis per silpnas arba aptiktas nutekintų slaptažodžių sąraše. Pasirinkite kitą, ilgesnį slaptažodį.";
  }
  if (code === "same_password") {
    return "Naujas slaptažodis turi skirtis nuo dabartinio.";
  }
  if (["session_not_found", "session_expired", "bad_jwt", "otp_expired"].includes(code)) {
    return "Atkūrimo nuoroda nebegalioja. Paprašykite naujos nuorodos.";
  }
  return fallback;
}

async function sendPasswordRecoveryEmail(email) {
  if (!supabase) throw new Error("Trūksta Supabase nustatymų Cloudflare aplinkoje.");
  const cleanEmail = String(email || "").trim();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cleanEmail)) {
    throw new Error("Įveskite galiojantį el. pašto adresą.");
  }
  const { error } = await supabase.auth.resetPasswordForEmail(cleanEmail, {
    redirectTo: passwordRecoveryRedirectUrl(),
  });
  if (error) {
    throw new Error(passwordRecoveryErrorMessage(error,
      "Nepavyko išsiųsti atkūrimo laiško. Bandykite dar kartą."));
  }
  return "Jeigu šiuo el. paštu yra registruota paskyra, išsiuntėme slaptažodžio atkūrimo nuorodą. Patikrinkite gautuosius ir šlamšto aplanką.";
}

async function updateRecoveredPassword(password, confirmation, expectedUserId) {
  if (!supabase) throw new Error("Trūksta Supabase nustatymų Cloudflare aplinkoje.");
  if (!expectedUserId) throw new Error("Atidarykite el. paštu gautą atkūrimo nuorodą.");
  if (password.length < 8) throw new Error("Slaptažodis turi būti bent 8 simbolių.");
  if (password !== confirmation) throw new Error("Įvesti slaptažodžiai nesutampa.");
  const { data, error: sessionError } = await supabase.auth.getUser();
  if (sessionError || data?.user?.id !== expectedUserId) {
    throw new Error("Atkūrimo sesija nebegalioja arba paskyra pasikeitė. Paprašykite naujos nuorodos.");
  }
  const { error } = await supabase.auth.updateUser({ password });
  if (error) {
    throw new Error(passwordRecoveryErrorMessage(error,
      "Nepavyko pakeisti slaptažodžio. Bandykite dar kartą."));
  }
}

function PasswordRecoveryPage({ user, checking, authorized, error, onDone }) {
  const [password, setPassword] = useState("");
  const [confirmation, setConfirmation] = useState("");
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);
  const [completed, setCompleted] = useState(false);
  const [requestOpen, setRequestOpen] = useState(() => new URLSearchParams(window.location.search).get("request") === "1");
  const submitting = useRef(false);
  const requestGeneration = useRef(0);

  useEffect(() => {
    requestGeneration.current += 1;
    submitting.current = false;
    setPassword("");
    setConfirmation("");
    setMessage("");
    setLoading(false);
    setCompleted(false);
    return () => { requestGeneration.current += 1; };
  }, [user?.id]);

  const unavailable = error || (!checking && (!user || !authorized)
    ? "Atkūrimo nuoroda nebegalioja arba jau panaudota. Paprašykite naujos nuorodos."
    : "");

  async function submit(event) {
    event.preventDefault();
    if (checking || unavailable || completed || submitting.current) return;
    submitting.current = true;
    const generation = requestGeneration.current;
    setMessage("");
    setLoading(true);
    try {
      await updateRecoveredPassword(password, confirmation, user?.id);
      if (generation !== requestGeneration.current) return;
      setPassword("");
      setConfirmation("");
      setCompleted(true);
      onDone();
    } catch (err) {
      if (generation === requestGeneration.current) {
        setMessage(err?.message || "Nepavyko pakeisti slaptažodžio.");
      }
    } finally {
      if (generation === requestGeneration.current) {
        submitting.current = false;
        setLoading(false);
      }
    }
  }

  const inputStyle = { width: "100%", border: "1px solid #dfe7ed", borderRadius: 10,
    padding: "12px 13px", font: "inherit" };
  const labelStyle = { display: "grid", gap: 6, fontSize: 14, fontWeight: 700 };

  return (
    <main style={{ minHeight: "100vh", display: "grid", placeItems: "center",
      padding: 20, background: "#f3f6f8" }}>
      <section aria-labelledby="password-recovery-title" style={{ width: "min(480px, 100%)",
        padding: 28, borderRadius: 20, background: "#fff", boxShadow: "0 16px 60px rgba(16,36,56,.12)" }}>
        <div className="eyebrow">SLAPTAŽODŽIO ATKŪRIMAS</div>
        <h1 id="password-recovery-title" style={{ fontSize: 28, margin: "8px 0 18px" }}>
          {completed ? "Slaptažodis pakeistas" : "Nustatykite naują slaptažodį"}
        </h1>
        {checking ? (
          <SilentLoader size={20} minHeight={42} />
        ) : unavailable ? (
          <>
            <p role="alert" style={{ color: "#a14425", lineHeight: 1.5 }}>{unavailable}</p>
            <button className="btn primary" type="button" onClick={() => setRequestOpen(true)}>
              Gauti naują nuorodą
            </button>
          </>
        ) : completed ? (
          <p role="status" style={{ lineHeight: 1.5 }}>Naujas slaptažodis išsaugotas. Atidaroma jūsų paskyra...</p>
        ) : (
          <form onSubmit={submit} style={{ display: "grid", gap: 14 }}>
            <p style={{ margin: "0 0 4px", color: "#526374", lineHeight: 1.5 }}>
              Pasirinkite bent 8 simbolių slaptažodį ir įveskite jį dar kartą.
            </p>
            <label style={labelStyle}>Naujas slaptažodis
              <input style={inputStyle} type="password" autoComplete="new-password"
                required minLength={8} value={password} disabled={loading}
                onChange={(event) => setPassword(event.target.value)} />
            </label>
            <label style={labelStyle}>Pakartokite slaptažodį
              <input style={inputStyle} type="password" autoComplete="new-password"
                required minLength={8} value={confirmation} disabled={loading}
                onChange={(event) => setConfirmation(event.target.value)} />
            </label>
            {message && <p role="alert" style={{ margin: 0, color: "#a14425", lineHeight: 1.5 }}>{message}</p>}
            <button className="btn primary" type="submit" disabled={loading}>
              {loading ? "Išsaugoma..." : "Išsaugoti naują slaptažodį"}
            </button>
          </form>
        )}
      </section>
      <AuthModal open={requestOpen} onClose={() => setRequestOpen(false)} initialMode="forgot" />
    </main>
  );
}

async function invokePhoneVerification(body) {
  if (!supabase) throw new Error("Trūksta svetainės nustatymų.");
  const { data, error } = await supabase.functions.invoke("phone-verification", { body });
  if (error) {
    let message = "Nepavyko patikrinti telefono. Bandykite vėliau.";
    try {
      const response = error.context?.clone?.() || error.context;
      const details = await response?.json?.();
      if (typeof details?.error === "string") message = details.error;
    } catch {}
    throw new Error(message);
  }
  if (data?.error) throw new Error(data.error);
  return data;
}

function loadSmsTurnstile() {
  if (window.turnstile) return Promise.resolve(window.turnstile);
  if (window.statybos24SmsTurnstile) return window.statybos24SmsTurnstile;
  window.statybos24SmsTurnstile = new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = "https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit";
    script.async = true;
    script.onload = () => window.turnstile ? resolve(window.turnstile) : reject(new Error("Patikra nepasiekiama."));
    script.onerror = () => {
      delete window.statybos24SmsTurnstile;
      script.remove();
      reject(new Error("Nepavyko įkelti patikros. Atnaujinkite puslapį."));
    };
    document.head.appendChild(script);
  });
  return window.statybos24SmsTurnstile;
}

function SmsCaptcha({ siteKey, resetKey, onToken, onError }) {
  const container = useRef(null);
  const callbacks = useRef({ onToken, onError });
  callbacks.current = { onToken, onError };
  useEffect(() => {
    let cancelled = false, widget = null;
    loadSmsTurnstile().then((api) => {
      if (cancelled || !container.current) return;
      widget = api.render(container.current, {
        sitekey: siteKey, action: "signup_phone", language: "lt", theme: "light",
        appearance: "interaction-only", size: "compact",
        callback: (token) => { if (!cancelled) callbacks.current.onToken(token); },
        "expired-callback": () => { if (!cancelled) callbacks.current.onToken(""); },
        "error-callback": () => {
          if (!cancelled) { callbacks.current.onToken(""); callbacks.current.onError("Patikra nepavyko. Atnaujinkite puslapį ir bandykite dar kartą."); }
        },
      });
    }).catch((error) => { if (!cancelled) callbacks.current.onError(error.message); });
    return () => { cancelled = true; if (widget !== null) window.turnstile?.remove(widget); };
  }, [siteKey, resetKey]);
  return <div ref={container} style={{ maxWidth: "100%" }} />;
}

function usePhoneVerification({ active, purpose, phone, email = "", userId = "" }) {
  const [config, setConfig] = useState(null);
  const [configError, setConfigError] = useState("");
  const [availability, setAvailability] = useState(null);
  const [availabilityRetry, setAvailabilityRetry] = useState(0);
  const [challenge, setChallenge] = useState(null);
  const [proof, setProof] = useState(null);
  const [code, setCode] = useState("");
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [captchaToken, setCaptchaToken] = useState("");
  const [captchaReset, setCaptchaReset] = useState(0);
  const [clock, setClock] = useState(Date.now());
  const normalizedPhone = normalizeLithuanianMobilePhone(phone);
  const normalizedEmail = String(email || "").trim().toLowerCase();
  const identity = JSON.stringify([active, purpose, normalizedPhone, normalizedEmail, userId]);
  const availabilityIdentity = JSON.stringify([active, purpose, normalizedPhone, userId]);
  const requestState = useRef({ identity, version: 0, busy: false });
  if (requestState.current.identity !== identity) {
    requestState.current = { identity, version: requestState.current.version + 1, busy: false };
  }

  useEffect(() => {
    setChallenge(null); setProof(null); setCode(""); setMessage(""); setError("");
    setBusy(false); setCaptchaToken(""); setCaptchaReset((v) => v + 1);
  }, [identity]);
  useEffect(() => {
    let cancelled = false;
    setConfig(null); setConfigError("");
    if (!active) return;
    invokePhoneVerification({ action: "status", purpose }).then((value) => {
      if (!cancelled) {
        if (typeof value?.enabled !== "boolean") throw new Error("Nepavyko patikrinti telefono nustatymų.");
        setConfig(value);
      }
    }).catch((error) => { if (!cancelled) setConfigError(error.message); });
    return () => { cancelled = true; };
  }, [active, purpose, userId]);
  useEffect(() => {
    if (!active || (!challenge && !proof)) return;
    const timer = window.setInterval(() => setClock(Date.now()), 1000);
    return () => window.clearInterval(timer);
  }, [active, challenge, proof]);

  useEffect(() => {
    let cancelled = false;
    if (!active || !normalizedPhone || !config || (purpose === "change" && normalizedPhone === config.current_phone)) return;
    setAvailability({ identity: availabilityIdentity, status: "checking" });
    const timer = window.setTimeout(() => {
      invokePhoneVerification({ action: "availability", purpose, phone: normalizedPhone }).then((value) => {
        if (cancelled) return;
        if (typeof value?.available !== "boolean") throw new Error("Nepavyko patikrinti numerio. Bandykite dar kartą.");
        setAvailability({ identity: availabilityIdentity, status: value.available ? "available" : "used" });
      }).catch((error) => {
        if (!cancelled) setAvailability({ identity: availabilityIdentity, status: "error", message: error.message });
      });
    }, 450);
    return () => { cancelled = true; window.clearTimeout(timer); };
  }, [availabilityIdentity, config?.current_phone, Boolean(config), availabilityRetry]);
  const availabilityStatus = !active || !normalizedPhone || (purpose === "change" && normalizedPhone === config?.current_phone)
    ? "not-required" : availability?.identity === availabilityIdentity ? availability.status : "checking";
  const availabilityError = availabilityStatus === "used" ? "Numeris jau naudojamas."
    : availabilityStatus === "error" ? availability.message || "Nepavyko patikrinti numerio. Bandykite dar kartą." : "";
  const checkingNumber = availabilityStatus === "checking";

  const required = Boolean(config?.enabled && (purpose === "signup" || normalizedPhone !== config.current_phone));
  const verified = Boolean(proof && proof.identity === identity && proof.expiresAt > clock);
  const retrySeconds = challenge?.identity === identity ? Math.max(0, Math.ceil((challenge.retryAt - clock) / 1000)) : 0;
  function requireProof() {
    if (configError) throw new Error(configError);
    if (!config) throw new Error("Palaukite, kol bus patikrinti telefono nustatymai.");
    if (availabilityError) throw new Error(availabilityError);
    if (checkingNumber) throw new Error("Palaukite, kol bus patikrintas numeris.");
    if (!required) return "";
    if (!proof || proof.identity !== identity || proof.expiresAt <= Date.now()) {
      throw new Error("Patvirtinkite telefono numerį SMS kodu.");
    }
    return proof.token;
  }
  async function act(action) {
    if (requestState.current.busy) return;
    const version = requestState.current.version;
    requestState.current.busy = true;
    setBusy(true); setError(""); setMessage("");
    try {
      if (!config?.enabled || !config.ready) throw new Error("SMS patvirtinimas dar neparuoštas. Bandykite vėliau.");
      if (!normalizedPhone) throw new Error("Įveskite galiojantį Lietuvos mobiliojo telefono numerį.");
      if (availabilityError) throw new Error(availabilityError);
      if (checkingNumber) throw new Error("Palaukite, kol bus patikrintas numeris.");
      if (purpose === "signup" && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalizedEmail)) throw new Error("Prieš siųsdami kodą įveskite el. paštą.");
      if (action === "send" && retrySeconds) throw new Error("Palaukite prieš siųsdami kodą dar kartą.");
      if (action === "send" && purpose === "signup" && !captchaToken) throw new Error("Atlikite patikrą prieš siųsdami SMS.");
      if (action === "verify" && (!challenge || challenge.identity !== identity || !/^\d{6}$/.test(code))) throw new Error("Įveskite gautą 6 skaitmenų SMS kodą.");
      if (action === "send") { setProof(null); setChallenge(null); setCode(""); }
      const value = await invokePhoneVerification({ action, purpose, phone: normalizedPhone, email: normalizedEmail,
        captcha_token: action === "send" ? captchaToken : undefined,
        challenge_id: action === "verify" ? challenge.id : undefined,
        code: action === "verify" ? code : undefined });
      if (requestState.current.version !== version) return;
      const now = Date.now(); setClock(now);
      if (action === "send") {
        if (!value?.challenge_id) throw new Error("Nepavyko išsiųsti SMS kodo.");
        setChallenge({ id: value.challenge_id, identity, retryAt: now + Number(value.retry_after || 60) * 1000 });
      } else {
        const expiresAt = new Date(value?.expires_at).getTime();
        if (!value?.proof || value.phone !== normalizedPhone || !Number.isFinite(expiresAt) || expiresAt <= now) throw new Error("Patvirtinimas nebegalioja. Paprašykite naujo kodo.");
        setProof({ token: value.proof, identity, expiresAt }); setCode("");
      }
    } catch (error) {
      if (requestState.current.version === version) setError(error.message || "Nepavyko patikrinti telefono.");
    } finally {
      if (requestState.current.version === version) {
        requestState.current.busy = false; setBusy(false);
        if (action === "send") { setCaptchaToken(""); setCaptchaReset((v) => v + 1); }
      }
    }
  }
  async function saveChange() {
    const token = requireProof();
    if (!token) return;
    const { data, error } = await supabase.rpc("sms_apply_phone_change", { p_proof: token });
    if (error) throw new Error(error.message || "Nepavyko išsaugoti patvirtinto numerio.");
    if (data?.phone !== normalizedPhone) throw new Error("Nepavyko išsaugoti patvirtinto numerio.");
    setConfig((current) => ({ ...current, current_phone: normalizedPhone }));
    setProof(null); setChallenge(null);
  }
  return { active, purpose, config, configError, required, verified, code, setCode, busy, message, error,
    availabilityError, checkingNumber, availabilityStatus, retryAvailability: () => { setAvailability(null); setAvailabilityRetry((v) => v + 1); },
    retrySeconds, captchaToken, setCaptchaToken, captchaReset, setError, challenge,
    send: () => act("send"), verify: () => act("verify"), requireProof, saveChange,
    unavailable: active && (!config || Boolean(configError) || checkingNumber || Boolean(availabilityError)),
  };
}

function PhoneAvailabilityHint({ verification: v }) {
  if (!v.active || (!v.checkingNumber && !v.availabilityError)) return null;
  if (!v.availabilityError) {
    return <SilentLoader size={14} minHeight={22} />;
  }
  return (
    <span role="alert" style={{ display: "block", marginTop: 5, fontSize: 13, color: "#ad381f" }}>
      {v.availabilityError}
    </span>
  );
}

function PhoneVerificationFields({ verification: v }) {
  if (!v.active) return null;
  const style = { gridColumn: "1 / -1", padding: 16, border: "1px solid #e2e8ee", borderRadius: 12,
    background: "#fff", fontSize: 14, lineHeight: 1.5 };
  const signup = v.purpose === "signup";
  if (v.configError) return <div style={style} role="alert">{v.configError} Atnaujinkite puslapį ir bandykite dar kartą.</div>;
  if (!v.config) return <div style={style} role="status">Ruošiamas patvirtinimas...</div>;
  if (v.availabilityStatus === "error") return <div style={style}>
    <button type="button" className="btn ghost" onClick={v.retryAvailability}>Tikrinti numerį dar kartą</button>
  </div>;
  if (!v.required || v.availabilityError) return null;
  if (!v.config.ready) return <div style={style} role="alert">SMS patvirtinimas šiuo metu nepasiekiamas. Bandykite vėliau.</div>;
  if (v.verified) return <div style={style} role="status">
    <b>{signup ? "Registracijos kodas patvirtintas" : "Telefono numeris patvirtintas"}</b>
    <p style={{ margin: "4px 0 0", color: "#526374" }}>{signup ? "Galite užbaigti registraciją." : "Išsaugokite pakeitimus."}</p>
  </div>;
  const canRequest = !v.checkingNumber && !v.availabilityError && !v.busy && v.retrySeconds === 0 && (!signup || Boolean(v.captchaToken));
  return (
    <div style={style}>
      <b style={{ color: "#142f46", fontSize: 15 }}>{v.challenge
        ? signup ? "Registracijai patvirtinti įveskite kodą" : "Telefono numeriui patvirtinti įveskite kodą"
        : signup ? "Registracijos patvirtinimas" : "Naujo telefono numerio patvirtinimas"}</b>
      <p style={{ margin: "5px 0 12px", color: "#526374" }}>{v.challenge
        ? "Įveskite į jūsų telefoną atsiųstą 6 skaitmenų kodą."
        : "Į jūsų telefoną atsiųsime 6 skaitmenų patvirtinimo kodą."}</p>
      {v.challenge ? <>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 10, alignItems: "end" }}>
        <label style={{ flex: "1 1 150px", minWidth: 0, color: "#142f46", fontSize: 13 }}>Patvirtinimo kodas
          <input type="text" inputMode="numeric" autoComplete="one-time-code" maxLength={6}
            aria-label="6 skaitmenų SMS kodas" placeholder="000000" value={v.code} disabled={v.busy} autoFocus
            onChange={(event) => v.setCode(event.target.value.replace(/\D/g, "").slice(0, 6))}
            style={{ width: "100%", boxSizing: "border-box", marginTop: 5, padding: "11px 12px", border: "1px solid #cad6df", borderRadius: 8,
              fontFamily: "inherit", fontSize: 20, lineHeight: 1.2, letterSpacing: "0.2em" }} />
        </label>
        <button type="button" className="btn primary" disabled={v.busy || v.code.length !== 6} onClick={v.verify}>
          {v.busy ? "Patvirtinama..." : "Patvirtinti kodą"}
        </button>
        </div>
        <div style={{ marginTop: 12 }}>
          {signup && !v.checkingNumber && v.retrySeconds === 0 && <SmsCaptcha siteKey={v.config.site_key} resetKey={v.captchaReset}
            onToken={v.setCaptchaToken} onError={v.setError} />}
          <button type="button" className="btn ghost" disabled={!canRequest} onClick={v.send} style={{ fontSize: 13 }}>
            {v.retrySeconds ? `Siųsti dar kartą po ${v.retrySeconds} s` : "Siųsti kodą dar kartą"}
          </button>
        </div>
      </> : <>
        {signup && !v.checkingNumber && <SmsCaptcha siteKey={v.config.site_key} resetKey={v.captchaReset}
          onToken={v.setCaptchaToken} onError={v.setError} />}
        <button type="button" className="btn primary" disabled={!canRequest} onClick={v.send}>
          {v.busy ? "Siunčiama..." : "Gauti SMS kodą"}
        </button>
      </>}
      {v.error && <p role="alert" style={{ margin: "10px 0 0", color: "#ad381f" }}>{v.error}</p>}
    </div>
  );
}

function AuthModal({
  open,
  onClose,
  initialMode = "login",
  initialRole = "worker",
  teamInvite = null,
}) {
  const [mode, setMode] = useState(initialMode);
  const [role, setRole] = useState(initialRole);
  const [form, setForm] = useState({
    firstName: "",
    lastName: "",
    birthDate: "",
    email: "",
    password: "",
    city: "Vilnius",
    phone: "",
    employerType: "company",
    companyName: "",
    companyCode: "",
  });
  const [message, setMessage] = useState("");
  const [success, setSuccess] = useState(false);
  const [loading, setLoading] = useState(false);
  const [termsAccepted, setTermsAccepted] = useState(false);
  const [termsOpen, setTermsOpen] = useState(false);
  const [privacyOpen, setPrivacyOpen] = useState(false);
  const submitting = useRef(false);
  const phoneVerification = usePhoneVerification({
    active: open && mode === "signup", purpose: "signup", phone: form.phone, email: form.email,
  });

  useEffect(() => {
    if (open) {
      setMode(initialMode);
      setRole(teamInvite ? "employer" : initialRole);
      setMessage("");
      setSuccess(false);
      setTermsAccepted(false);

      if (teamInvite) {
        const invitedName = String(teamInvite.invited_name || "").trim();
        const invitedParts = invitedName.split(/\s+/).filter(Boolean);
        setForm((current) => ({
          ...current,
          firstName: invitedParts[0] || current.firstName,
          lastName: invitedParts.slice(1).join(" ") || current.lastName,
          email: teamInvite.email || current.email,
        }));
      }
    }
  }, [open, initialMode, initialRole, teamInvite]);

  if (!open) return null;

  const setField = (key) => (e) =>
    setForm((current) => ({ ...current, [key]: e.target.value }));

  async function submit(e) {
    e.preventDefault();
    if (submitting.current) return;
    setMessage("");
    setSuccess(false);

    if (!supabase) {
      setMessage("Trūksta Supabase nustatymų Cloudflare aplinkoje.");
      return;
    }

    if (!form.email.trim() || (mode !== "forgot" && !form.password)) {
      setMessage(mode === "forgot" ? "Įveskite el. pašto adresą." : "Įveskite el. paštą ir slaptažodį.");
      return;
    }

    submitting.current = true;
    setLoading(true);

    try {
      if (mode === "forgot") {
        const result = await sendPasswordRecoveryEmail(form.email);
        setSuccess(true);
        setMessage(result);
      } else if (mode === "login") {
        const { error } = await supabase.auth.signInWithPassword({
          email: form.email.trim(),
          password: form.password,
        });

        if (error) throw error;
        onClose();
      } else {
        if (!termsAccepted) {
          throw new Error("Norėdami registruotis, susipažinkite su naudojimosi sąlygomis ir jas patvirtinkite.");
        }
        if (!form.firstName.trim()) {
          throw new Error("Įveskite vardą.");
        }
        if (!form.lastName.trim()) {
          throw new Error("Įveskite pavardę.");
        }
        if (role === "worker") {
          const birthDateError = workerBirthDateError(form.birthDate, true);
          if (birthDateError) throw new Error(birthDateError);
        }

        if (form.password.length < 8) {
          throw new Error("Slaptažodis turi būti bent 8 simbolių.");
        }

        if (!form.phone.trim()) {
          throw new Error(
            "Registracijai galiojantis Lietuvos mobiliojo telefono numeris yra privalomas."
          );
        }

        const normalizedPhone = normalizeLithuanianMobilePhone(form.phone);
        if (!normalizedPhone) {
          throw new Error(
            "Įveskite galiojantį Lietuvos mobiliojo telefono numerį, pvz. +37061234567."
          );
        }

        if (
          role === "employer" &&
          !teamInvite &&
          form.employerType === "company" &&
          !form.companyName.trim()
        ) {
          throw new Error("Įveskite įmonės pavadinimą.");
        }

        const phoneProof = phoneVerification.requireProof();
        const canonicalCity = await canonicalCityName(form.city);
        if (!canonicalCity) {
          throw new Error("Pasirinkite miestą iš pasiūlymų sąrašo.");
        }

        const { data, error } = await supabase.auth.signUp({
          email: form.email.trim(),
          password: form.password,
          options: {
            emailRedirectTo: teamInvite?.token
              ? companyTeamInviteLink(teamInvite.token)
              : window.location.origin,
            data: {
              terms_accepted: true,
              terms_version: TERMS_VERSION,
              role: teamInvite ? "employer" : role,
              preferred_plan: "basic",
              preferred_billing_interval: "monthly",
              first_name: form.firstName.trim(),
              last_name: form.lastName.trim(),
              ...(role === "worker" ? { birth_date: form.birthDate } : {}),
              display_name: `${form.firstName.trim()} ${form.lastName.trim()}`.trim(),
              legal_name: `${form.firstName.trim()} ${form.lastName.trim()}`.trim(),
              city: canonicalCity,
              phone: normalizedPhone,
              ...(phoneProof ? { phone_verification_proof: phoneProof } : {}),
              employer_type:
                role === "employer" && !teamInvite
                  ? form.employerType
                  : "",
              company_name:
                role === "employer" && !teamInvite
                  ? form.employerType === "individual"
                    ? `${form.firstName.trim()} ${form.lastName.trim()}`.trim()
                    : form.companyName.trim()
                  : "",
              company_code:
                role === "employer" && !teamInvite && form.employerType === "company"
                  ? form.companyCode.trim()
                  : "",
            },
          },
        });

        if (error) throw error;

        if (data.session) {
          onClose();
        } else {
          setSuccess(true);
          setMessage(
            "Registracija sėkminga. Patikrinkite el. paštą ir patvirtinkite paskyrą."
          );
        }
      }
    } catch (error) {
      setMessage(error?.message || "Nepavyko. Bandykite dar kartą.");
    } finally {
      submitting.current = false;
      setLoading(false);
    }
  }

  const overlay = {
    position: "fixed",
    inset: 0,
    background: "rgba(16,36,56,.58)",
    zIndex: 1000,
    display: "grid",
    placeItems: "center",
    padding: 20,
  };

  const card = {
    width: "min(520px, 100%)",
    maxHeight: "calc(100dvh - 40px)",
    overflow: "hidden",
    background: "#fff",
    borderRadius: 20,
    boxShadow: "0 24px 80px rgba(16,36,56,.24)",
    padding: 0,
  };

  const cardScroll = {
    maxHeight: "calc(100dvh - 40px)",
    overflowY: "auto",
    padding: 28,
    boxSizing: "border-box",
    scrollbarGutter: "stable",
  };

  const twoColumns = {
    display: "grid",
    gridTemplateColumns: "1fr 1fr",
    gap: 10,
  };

  const tabStyle = (active) => ({
    border: "1px solid #dfe7ed",
    borderRadius: 10,
    padding: "11px 12px",
    background: active ? "#102438" : "#fff",
    color: active ? "#fff" : "#102438",
    fontWeight: 700,
    cursor: "pointer",
  });

  const labelStyle = {
    display: "grid",
    gap: 6,
    fontSize: 14,
    fontWeight: 700,
  };

  const inputStyle = {
    width: "100%",
    border: "1px solid #dfe7ed",
    borderRadius: 10,
    padding: "12px 13px",
    font: "inherit",
    outline: "none",
  };

  return (
    <div
      style={overlay}
      onMouseDown={(e) => {
        if (e.target === e.currentTarget && !loading) onClose();
      }}
    >
      <div style={card} role="dialog" aria-modal="true" aria-labelledby="auth-modal-title">
        <div style={cardScroll}>
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            gap: 16,
            alignItems: "flex-start",
            marginBottom: 20,
          }}
        >
          <div>
            <div className="eyebrow">
              {mode === "forgot" ? "SLAPTAŽODŽIO ATKŪRIMAS" : mode === "login" ? "PRISIJUNGIMAS" : "REGISTRACIJA"}
            </div>
            <h2 id="auth-modal-title" style={{ margin: "6px 0 0", fontSize: 30 }}>
              {mode === "forgot" ? "Pamiršote slaptažodį?" : mode === "login" ? "Sveiki sugrįžę" : "Sukurkite paskyrą"}
            </h2>
          </div>

          <button
            type="button"
            onClick={onClose}
            disabled={loading}
            aria-label="Uždaryti"
            style={{
              border: 0,
              background: "#f3f6f8",
              borderRadius: 10,
              width: 38,
              height: 38,
              cursor: "pointer",
              fontSize: 20,
            }}
          >
            <CloseMark />
          </button>
        </div>

        <div style={{ ...twoColumns, marginBottom: 18 }}>
          <button
            type="button"
            style={tabStyle(mode === "login")}
            disabled={loading}
            onClick={() => {
              setMode("login");
              setMessage("");
              setSuccess(false);
            }}
          >
            Prisijungti
          </button>
          <button
            type="button"
            style={tabStyle(mode === "signup")}
            disabled={loading}
            onClick={() => {
              setMode("signup");
              setMessage("");
              setSuccess(false);
            }}
          >
            Registruotis
          </button>
        </div>

        {mode === "signup" && !teamInvite && (
          <div style={{ ...twoColumns, marginBottom: 18 }}>
            <button
              type="button"
              style={tabStyle(role === "worker")}
              onClick={() => setRole("worker")}
            >
              Ieškau darbo
            </button>
            <button
              type="button"
              style={tabStyle(role === "employer")}
              onClick={() => setRole("employer")}
            >
              Ieškau darbuotojų
            </button>
          </div>
        )}

        <form onSubmit={submit} style={{ display: "grid", gap: 13 }}>
          {mode === "signup" && (
            <>
              {role === "employer" && !teamInvite && (
                <>
                  <div style={{ display: "grid", gap: 7 }}>
                    <span style={{ fontSize: 14, fontWeight: 800, color: "#102438" }}>
                      Darbdavio tipas
                    </span>
                    <div
                      style={{
                        display: "grid",
                        gridTemplateColumns: "1fr 1fr",
                        gap: 8,
                        padding: 4,
                        borderRadius: 12,
                        background: "#f1f4f6",
                      }}
                    >
                      {[
                        ["company", "Įmonė"],
                        ["individual", "Privatus asmuo"],
                      ].map(([value, label]) => (
                        <button
                          key={value}
                          type="button"
                          onClick={() =>
                            setForm((current) => ({
                              ...current,
                              employerType: value,
                              ...(value === "individual"
                                ? { companyName: "", companyCode: "" }
                                : {}),
                            }))
                          }
                          style={{
                            minHeight: 42,
                            border: 0,
                            borderRadius: 9,
                            background: form.employerType === value ? "#fff" : "transparent",
                            color: "#102438",
                            font: "inherit",
                            fontSize: 13,
                            fontWeight: 800,
                            cursor: "pointer",
                            boxShadow:
                              form.employerType === value
                                ? "0 1px 5px rgba(16,36,56,.10)"
                                : "none",
                          }}
                        >
                          {label}
                        </button>
                      ))}
                    </div>
                  </div>

                  {form.employerType === "company" && (
                    <div style={twoColumns}>
                      <label style={labelStyle}>
                        Įmonės pavadinimas *
                        <input
                          style={inputStyle}
                          value={form.companyName}
                          onChange={setField("companyName")}
                          placeholder="UAB Statyba"
                          required
                        />
                      </label>

                      <label style={labelStyle}>
                        Įmonės kodas
                        <input
                          style={inputStyle}
                          value={form.companyCode}
                          onChange={setField("companyCode")}
                          placeholder="123456789"
                        />
                      </label>
                    </div>
                  )}
                </>
              )}

              <div style={twoColumns}>
                <label style={labelStyle}>
                  Vardas *
                  <input
                    style={inputStyle}
                    value={form.firstName}
                    onChange={setField("firstName")}
                    placeholder="Pvz. Tomas"
                    autoComplete="given-name"
                    required
                  />
                </label>

                <label style={labelStyle}>
                  Pavardė *
                  <input
                    style={inputStyle}
                    value={form.lastName}
                    onChange={setField("lastName")}
                    placeholder="Pvz. Jonaitis"
                    autoComplete="family-name"
                    required
                  />
                </label>
              </div>

              {role === "worker" && (
                <label style={labelStyle}>
                  Gimimo data *
                  <input
                    style={{ ...inputStyle, boxSizing: "border-box", minWidth: 0 }}
                    type="date"
                    min="1900-01-01"
                    max={getVilniusTodayISO()}
                    value={form.birthDate}
                    onChange={setField("birthDate")}
                    autoComplete="bday"
                    required
                  />
                  <span style={{ color: "#71808d", fontSize: 11, fontWeight: 400 }}>
                    Gimimo data nėra rodoma darbdaviams.
                  </span>
                </label>
              )}

              <div style={twoColumns}>
                <label style={labelStyle}>
                  Miestas
                  <CityAutocomplete
                    style={inputStyle}
                    value={form.city}
                    onChange={(value) =>
                      setForm((current) => ({ ...current, city: value }))
                    }
                    placeholder="Pradėkite rašyti miestą"
                  />
                </label>

                <label style={labelStyle}>
                  Telefonas *
                  <input
                    style={inputStyle}
                    value={form.phone}
                    onChange={setField("phone")}
                    onBlur={() => {
                      const normalized = normalizeLithuanianMobilePhone(form.phone);
                      if (normalized) {
                        setForm((current) => ({ ...current, phone: normalized }));
                      }
                    }}
                    placeholder="+37061234567"
                    autoComplete="tel"
                    inputMode="tel"
                    required
                  />
                  <PhoneAvailabilityHint verification={phoneVerification} />
                </label>
              </div>
            </>
          )}

          {mode === "forgot" && (
            <p style={{ margin: 0, color: "#526374", lineHeight: 1.5 }}>
              Įveskite paskyros el. paštą. Atsiųsime nuorodą naujam slaptažodžiui nustatyti.
            </p>
          )}

          <label style={labelStyle}>
            El. paštas
            <input
              style={inputStyle}
              type="email"
              value={form.email}
              onChange={setField("email")}
              placeholder="vardas@email.lt"
              autoComplete="email"
              readOnly={Boolean(teamInvite) && mode !== "forgot"}
              disabled={loading}
              required
            />
          </label>

          {mode !== "forgot" && <label style={labelStyle}>
            Slaptažodis
            <input
              style={inputStyle}
              type="password"
              required
              minLength={mode === "signup" ? 8 : undefined}
              value={form.password}
              onChange={setField("password")}
              placeholder={
                mode === "signup" ? "Bent 8 simboliai" : "Jūsų slaptažodis"
              }
              autoComplete={
                mode === "signup" ? "new-password" : "current-password"
              }
            />
          </label>}

          {mode === "signup" && <PhoneVerificationFields verification={phoneVerification} />}

          {mode === "login" && (
            <button type="button" disabled={loading}
              onClick={() => {
                setMode("forgot");
                setForm((current) => ({ ...current, password: "" }));
                setMessage("");
                setSuccess(false);
              }}
              style={{ border: 0, padding: 0, background: "none", color: "#b85f0e",
                font: "inherit", fontSize: 13, lineHeight: 1.2, fontWeight: 750,
                cursor: "pointer", textAlign: "right" }}>
              Pamiršau slaptažodį
            </button>
          )}

          {mode === "signup" && (
            <label style={{ display: "flex", alignItems: "flex-start", gap: 10, color: "#405264", fontSize: 13, lineHeight: 1.5 }}>
              <input
                type="checkbox"
                checked={termsAccepted}
                onChange={(event) => setTermsAccepted(event.target.checked)}
                required
                style={{ marginTop: 3, accentColor: "#f08a28", width: 17, height: 17, flexShrink: 0 }}
              />
              <span>
                Susipažinau ir sutinku su{" "}
                <button type="button" onClick={(event) => { event.preventDefault(); setTermsOpen(true); }} style={{ border: 0, background: "none", padding: 0, color: "#b85f0e", font: "inherit", fontWeight: 800, textDecoration: "underline", cursor: "pointer" }}>
                  naudojimosi sąlygomis
                </button>{" "}ir susipažinau su{" "}
                <button type="button" onClick={(event) => { event.preventDefault(); setPrivacyOpen(true); }} style={{ border: 0, background: "none", padding: 0, color: "#b85f0e", font: "inherit", fontWeight: 800, textDecoration: "underline", cursor: "pointer" }}>
                  privatumo politika
                </button>.
              </span>
            </label>
          )}

          {message && (
            <div
              role={success ? "status" : "alert"}
              style={{
                padding: "11px 12px",
                borderRadius: 10,
                background: success ? "#edf8f3" : "#fff3ed",
                color: "#102438",
                fontSize: 14,
                lineHeight: 1.45,
              }}
            >
              {message}
            </div>
          )}

          <button
            className="btn primary"
            type="submit"
            disabled={loading || (mode === "signup" && (phoneVerification.busy || phoneVerification.unavailable || (phoneVerification.required && !phoneVerification.verified)))}
            style={{
              width: "100%",
              justifyContent: "center",
              marginTop: 4,
              opacity: loading ? 0.7 : 1,
            }}
          >
            {loading
              ? <SilentLoader size={16} minHeight={18} />
              : mode === "forgot"
              ? "Siųsti atkūrimo nuorodą"
              : mode === "login"
              ? "Prisijungti"
              : phoneVerification.config?.enabled ? "Užbaigti registraciją" : "Sukurti paskyrą"}
          </button>
        </form>
        </div>
        <PlatformTermsDialog open={termsOpen} onClose={() => setTermsOpen(false)} />
        <PlatformPrivacyDialog open={privacyOpen} onClose={() => setPrivacyOpen(false)} />
      </div>
    </div>
  );
}


