function HireSideIcon({ type }) {
  const common = { fill: "none", stroke: "currentColor", strokeWidth: 1.8, strokeLinecap: "round", strokeLinejoin: "round" };
  if (type === "overview") return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 10.8 12 4l8 6.8V20a1 1 0 0 1-1 1h-5v-6h-4v6H5a1 1 0 0 1-1-1v-9.2Z" {...common}/></svg>;
  if (type === "method") return <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="6" cy="6" r="2" {...common}/><circle cx="18" cy="12" r="2" {...common}/><circle cx="6" cy="18" r="2" {...common}/><path d="M8 6h4a4 4 0 0 1 4 4M8 18h4a4 4 0 0 0 4-4" {...common}/></svg>;
  if (type === "trades") return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20V9l8-5 8 5v11H4Z" {...common}/><path d="M8 20v-6h8v6M8 10h.01M12 10h.01M16 10h.01" {...common}/></svg>;
  if (type === "conditions") return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M7 4v6M17 4v6M5 11h14a1 1 0 0 1 1 1v7H4v-7a1 1 0 0 1 1-1Z" {...common}/><path d="M8 15h3M14 15h2" {...common}/></svg>;
  if (type === "request") return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h10v4H7V3Z" {...common}/><path d="M6 5H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1M7 12h10M7 16h7" {...common}/></svg>;
  if (type === "faq") return <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9" {...common}/><path d="M9.8 9a2.4 2.4 0 1 1 3.3 2.2c-.8.4-1.1.9-1.1 1.8M12 17h.01" {...common}/></svg>;
  if (type === "login") return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 5H6a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h4" {...common}/><path d="M14 8l4 4-4 4M18 12H9" {...common}/></svg>;
  return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 6h16v12H4V6Z" {...common}/><path d="m5 7 7 6 7-6" {...common}/></svg>;
}

function HireInput({ label, required = false, hint, error, ...props }) {
  return (
    <label className="hire-field">
      <span className="hire-label">{label}{required ? <b aria-hidden="true">*</b> : null}</span>
      <input className={`hire-input${error ? " invalid" : ""}`} {...props} />
      {hint && !error ? <span className="hire-hint">{hint}</span> : null}
      {error ? <span className="hire-error">{error}</span> : null}
    </label>
  );
}

function HireDropdown({
  value,
  onChange,
  options,
  placeholder = "Select",
  ariaLabel = "Select",
  disabled = false,
  invalid = false,
  compact = false,
  placement = "down",
  align = "left",
  className = "",
  displayLabel = "",
}) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef(null);
  const triggerRef = useRef(null);
  const normalizedOptions = options.map((option) =>
    typeof option === "string" ? { value: option, label: option } : option
  );
  const selected = normalizedOptions.find((option) => option.value === value);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event) => {
      if (!rootRef.current?.contains(event.target)) setOpen(false);
    };
    const onKeyDown = (event) => {
      if (event.key === "Escape") {
        setOpen(false);
        triggerRef.current?.focus();
      }
    };
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [open]);

  return (
    <span
      ref={rootRef}
      className={[
        "hire-dropdown",
        open ? "open" : "",
        compact ? "compact" : "",
        placement === "up" ? "drop-up" : "",
        align === "right" ? "align-right" : "",
        className,
      ].filter(Boolean).join(" ")}
    >
      <button
        ref={triggerRef}
        type="button"
        className={`hire-dropdown-trigger${invalid ? " invalid" : ""}`}
        aria-label={ariaLabel}
        aria-haspopup="listbox"
        aria-expanded={open}
        disabled={disabled}
        onClick={() => setOpen((current) => !current)}
        onKeyDown={(event) => {
          if ((event.key === "ArrowDown" || event.key === "Enter" || event.key === " ") && !open) {
            event.preventDefault();
            setOpen(true);
            requestAnimationFrame(() => rootRef.current?.querySelector('[role="option"]')?.focus());
          }
        }}
      >
        <span className={!selected ? "placeholder" : ""}>{displayLabel || selected?.label || placeholder}</span>
        <svg className="hire-dropdown-chevron" viewBox="0 0 20 20" aria-hidden="true">
          <path d="m5 7.5 5 5 5-5" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </button>

      {open && !disabled ? (
        <span className="hire-dropdown-menu" role="listbox" aria-label={ariaLabel}>
          {normalizedOptions.map((option) => {
            const active = option.value === value;
            return (
              <button
                key={option.value}
                type="button"
                role="option"
                aria-selected={active}
                className={active ? "active" : ""}
                onClick={() => {
                  onChange(option.value);
                  setOpen(false);
                  triggerRef.current?.focus();
                }}
                onKeyDown={(event) => {
                  if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return;
                  event.preventDefault();
                  const buttons = [...rootRef.current.querySelectorAll('[role="option"]')];
                  const current = buttons.indexOf(event.currentTarget);
                  const next = current + (event.key === "ArrowDown" ? 1 : -1);
                  buttons[(next + buttons.length) % buttons.length]?.focus();
                }}
              >
                <span>{option.label}</span>
                {active ? (
                  <svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 10.2 3.1 3.1L15 6.7" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>
                ) : null}
              </button>
            );
          })}
        </span>
      ) : null}
    </span>
  );
}

function HireSelect({ label, required = false, value, onChange, options, placeholder = "Select", error, disabled = false }) {
  return (
    <div className="hire-field">
      <span className="hire-label">{label}{required ? <b aria-hidden="true">*</b> : null}</span>
      <HireDropdown
        value={value}
        onChange={onChange}
        options={options}
        placeholder={placeholder}
        ariaLabel={label}
        disabled={disabled}
        invalid={Boolean(error)}
      />
      {error ? <span className="hire-error">{error}</span> : null}
    </div>
  );
}

function HireSegment({ value, onChange, options, ariaLabel }) {
  return (
    <div className="hire-segment" role="group" aria-label={ariaLabel}>
      {options.map((option) => (
        <button
          key={option.value}
          type="button"
          className={value === option.value ? "active" : ""}
          aria-pressed={value === option.value}
          onClick={() => onChange(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}


